# /// script
# requires-python = ">=3.11"
# dependencies = []
# ///
"""Check that every accepted refund is grounded in a usable return policy."""

from kitaru.api_models.v1.evaluation import EvaluationResult
from kitaru.api_models.v1.session_node import NodeType
from kitaru.task.evaluator import SessionView


def evaluate(session: SessionView) -> EvaluationResult:
    """Fail when a refund was accepted without a matching policy rule."""
    policy_found = None
    refund_accepted = False
    for node in session.nodes:
        if node.node_type is not NodeType.TOOL_CALL:
            continue
        outputs = node.outputs if isinstance(node.outputs, dict) else {}
        if node.tool_name == "get_return_policy":
            policy_found = outputs.get("found")
        if node.tool_name == "issue_refund" and outputs.get("accepted") is True:
            refund_accepted = True

    if not refund_accepted:
        return EvaluationResult(
            name="policy_grounded_refund",
            value="pass",
            passed=True,
            explanation="No refund was issued, so no policy grounding is required.",
        )
    if policy_found is True:
        return EvaluationResult(
            name="policy_grounded_refund",
            value="pass",
            passed=True,
            explanation="The accepted refund follows a matched return policy.",
        )
    return EvaluationResult(
        name="policy_grounded_refund",
        value="fail",
        passed=False,
        explanation=(
            "A refund was accepted although the policy lookup returned no "
            "usable rule; the agent should escalate instead."
        ),
    )
